/**
 * @distilled.cloud/namespacelabs -- Namespace (namespace.so) SDK for Effect.
 *
 * `./services` and `./unstable-services` are generated by
 * `scripts/generate.ts` from the Smithy models that `scripts/convert.ts`
 * converts from Namespace's public protobuf API (`buf.build/namespace/cloud`).
 * Services in `v1beta` and `namespace.experimental.*` packages are under
 * `@distilled.cloud/namespacelabs/unstable/<name>`. Everything else in this
 * folder is hand-written.
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as NamespaceLabs from "@distilled.cloud/namespacelabs";
 * import * as Compute from "@distilled.cloud/namespacelabs/unstable/compute";
 *
 * const program = Effect.gen(function* () {
 *   const created = yield* Compute.createInstance({
 *     shape: { virtualCpu: 2, memoryMegabytes: 4096, os: "linux", machineArch: "amd64" },
 *     deadline: new Date(Date.now() + 10 * 60 * 1000).toISOString(),
 *   });
 *   const instanceId = created.metadata?.instanceId;
 *   if (instanceId === undefined) return undefined;
 *   const instance = yield* Compute.describeInstance({ instanceId });
 *   yield* Compute.destroyInstance({ instanceId });
 *   return instance.metadata?.status;
 * });
 *
 * const Live = Layer.mergeAll(
 *   FetchHttpClient.layer,
 *   NamespaceLabs.CredentialsFromEnv,
 * );
 *
 * program.pipe(Effect.provide(Live), Effect.runPromise);
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  NamespaceLabsProtocol,
  baseUrlFor,
  hostFor,
  type Host,
  type NamespaceLabsOpError,
  type NamespaceLabsOpContext,
} from "./protocol.ts";
export { paginateCursor } from "./pagination.ts";
export * as Retry from "./retry.ts";
